export const PRAYER_ART_EDITORIAL_SLOTS_V1=Object.freeze(Object.fromEntries(
  rows.map(([id,row])=>[id,Object.freeze({...row,slot:id,selected:row.selected?Object.freeze(row.selected):null})])
));
export function prayerEditorialSlot(id){
  const key=String(id??"");
  return Object.hasOwn(PRAYER_ART_EDITORIAL_SLOTS_V1,key)?PRAYER_ART_EDITORIAL_SLOTS_V1[key]:null;
}
